INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT128-S2-Q8$batch13$, 128, 2, 8, $batch13$Role$batch13$, $batch13$Candidate: The children in our nation need a better education. My opponent maintains that our outdated school system is the major impediment to achieving this goal. In fact our school system does need reform. Nonetheless, my opponent's position places far too much blame on our schools, for it seems to equate education with schooling, yet other parts of society are at least as responsible for educating our youth as our schools are.$batch13$, $batch13$The statement that the school system needs reform figures in the candidate's argument in which one of the following ways?$batch13$, $batch13$E$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=128 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT128-S2-Q8$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$It is the main conclusion that the argument is attempting to establish about the position of the candidate's opponent.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT128-S2-Q8$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$It is offered as an example of one of the social problems for which the argument proposes a solution.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT128-S2-Q8$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$It is cited as establishing the candidate's contention that far too much is being blamed on schools.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT128-S2-Q8$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$It is used to indicate how the failings of the school system are partially responsible for society's problems.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT128-S2-Q8$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$It is a limited concession made to the candidate's opponent in the context of a broader challenge to the opponent's position.$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT128-S2-Q8$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT128-S2-Q8$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Opposing Point$batch13$, $batch13$The opponent says the outdated school system is the major obstacle to better education.$batch13$), (1, $batch13$Concession$batch13$, $batch13$The school system does need reform.$batch13$), (2, $batch13$Conclusion$batch13$, $batch13$The opponent's position puts far too much blame on the schools.$batch13$), (3, $batch13$Evidence$batch13$, $batch13$The position equates education with schooling, yet other parts of society are at least as responsible for educating young people.$batch13$), (4, $batch13$Evaluate$batch13$, $batch13$"In fact our school system does need reform" agrees with part of the opponent's view. "Nonetheless" then turns to the candidate's real challenge. So the claim grants the opponent a point before attacking the larger position.$batch13$), (5, $batch13$Goal$batch13$, $batch13$A limited concession within a broader challenge.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT128-S2-Q8$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$The main conclusion is that the opponent puts too much blame on schools, not that schools need reform.$batch13$), ($batch13$B$batch13$, $batch13$The candidate proposes no solution.$batch13$), ($batch13$C$batch13$, $batch13$Schools needing reform doesn't support "too much blame". It cuts the other way, which is why "Nonetheless" follows it.$batch13$), ($batch13$D$batch13$, $batch13$The candidate never says school failings cause society's problems.$batch13$), ($batch13$E$batch13$, $batch13$The candidate grants that schools need reform, then argues the opponent overstates their role.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT128-S2-Q8$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
